"""Synthetic independent review of frozen E2/E3 contrast/bootstrap contract."""
import hashlib,importlib.util,json,pathlib
import numpy as np
B=pathlib.Path(__file__).resolve().parents[1];D=B/'e2_e3_analysis';sha=lambda p:hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest();load=lambda p:json.loads(pathlib.Path(p).read_text())
spec=importlib.util.spec_from_file_location('e2e3_stats',D/'paired.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
plan=load(D/'plan.json');start=load(D/'monitor_cpu002/started.json');term=load(D/'monitor_cpu002/terminal.json');assert term['reason']=='completed' and term['worker_returncode']==0 and not term['remaining_process_group'] and start['worker_pid']==term['worker_pid']
coef={'E2_leave_slot0':{'111':1,'011':-1},'E2_leave_slot1':{'111':1,'101':-1},'E2_leave_slot2':{'111':1,'110':-1},'E2_only_slot0':{'100':1,'000':-1},'E2_only_slot1':{'010':1,'000':-1},'E2_only_slot2':{'001':1,'000':-1},'E2_three_way':{'111':1,'110':-1,'101':-1,'011':-1,'100':1,'010':1,'001':1,'000':-1},'E3_match_minus_perm':{'111':1,'PERM':-1},'E3_match_minus_mean':{'111':1,'MEAN':-1},'E3_perm_minus_off':{'PERM':1,'000':-1},'E3_mean_minus_off':{'MEAN':1,'000':-1}}
rng=np.random.default_rng(84);data=rng.uniform(size=(5,10));groups=['a','a','b','c','c'];rows=[{'group_id':g,'scores':dict(zip(m.CONFIGS,data[i]))} for i,g in enumerate(groups)];o=m.analyze(rows,replicates=731,seed=19);draw=np.random.default_rng(19).integers(0,3,size=(731,3));ix=[np.flatnonzero(np.array(groups)==g) for g in sorted(set(groups))]
for name,weights in coef.items():
 w=np.asarray([weights.get(k.split('/')[1],0.) for k in m.CONFIGS]);per=data@w;means=np.asarray([sum(per[ix[j]]) for j in range(3)]);sizes=np.array([len(x) for x in ix]);boots=100*means[draw].sum(axis=1)/sizes[draw].sum(axis=1);alpha=.05/3 if name.startswith('E2_leave') else .05;got=o['contrasts'][name]
 assert np.isclose(got['difference_pp'],100*per.mean()) and np.allclose(got['percentile_ci_pp'],np.quantile(boots,[alpha/2,1-alpha/2])) and np.isclose(got['nominal_coverage'],1-alpha)
 assert got['positive_questions']==int((per>1e-12).sum()) and got['negative_questions']==int((per< -1e-12).sum())
assert o['n_questions']==5 and o['n_image_groups']==3 and plan['bootstrap']['replicates']==10000
out=B/'e1_independent_review/e2e3_stats_review.json';assert not out.exists();out.write_text(json.dumps({'status':'passed','scope':'synthetic CPU statistics contract only, no scoring or GT','plan_sha256':sha(D/'plan.json'),'source_sha256':sha(D/'paired.py'),'test_sha256':sha(D/'test_paired.py'),'prior_cpu_started_sha256':sha(D/'monitor_cpu002/started.json'),'prior_cpu_terminal_sha256':sha(D/'monitor_cpu002/terminal.json'),'reviewer_sha256':sha(__file__),'contrasts_verified':len(coef),'checks':['independent unequal-cluster resampling','all signed contrasts','Bonferroni 98.333% primary intervals','95% exploratory intervals','question weighting and positive/negative counts'],'GT_opened':False,'scoring_performed':False},indent=2)+'\n');print('passed',sha(out))
